const card=([name,value,icon])=>`<button class="metric-card" data-name="${name}" data-value="${value}"><span class="metric-head"><span class="icon-tile">${icon}</span><span><span class="metric-name">${name}</span><span class="metric-value">${value}</span></span></span>${spark}</button>`;

let dropdownId=0;
function dropdown(label,options,small=''){const id='dd-'+(++dropdownId);return `<div class="filter-wrap ${small}"><button class="filter" data-filter="${id}">${label}<span>⌄</span></button><div class="menu" data-menu="${id}">${options.map(o=>`<button>${o}</button>`).join('')}</div></div>`}
function dashboardTopbar(){return `<div class="dashboard-filters">${dropdown('General',['General','New Business','Protection'],'compact')}${dropdown('All Advisors',['All Advisors','Darran Brindley','Sarah Taylor','Michael Davis'])}${dropdown('This Week',['This Week','Last Week','This Month','This Quarter'])}</div>`}
function breadcrumb(parent,title,action=''){return `<div class="crumb"><b>${parent}</b>${title?`<span>›</span><b>${title}</b>`:''}</div>${action?`<button class="top-action" data-add="${action}"><span>＋</span>${action}</button>`:''}`}
function dashboard(){return `<section class="section-title-row"><h1 class="section-heading">Mortgages</h1><span class="live">LIVE</span></section><button class="hero-card" data-name="Referrals Received" data-value="18"><span class="label">Referrals Received</span><span class="hero-metric"><strong>18</strong>${spark}</span></button><div class="metric-grid">${mortgageCards.map(card).join('')}</div><h2 class="section-heading protection">Protection</h2><div class="metric-grid wide">${[['Premium Submitted','£6,840'],['Premium on Risk','£4,920']].map(x=>`<button class="metric-card" data-name="${x[0]}" data-value="${x[1]}"><span class="metric-name">${x[0]}</span><span class="metric-value">${x[1]}</span>${spark}</button>`).join('')}</div><div class="metric-grid lower-grid">${protectionCards.map(card).join('')}</div>`}

function tools(search,extras=''){return `<div class="list-tools"><label class="search-box">⌕<input data-search placeholder="${search}"></label>${extras}</div>`}
function pager(count){return `<div class="pager"><span>Showing 1 - ${count} of ${count}</span><span class="pages">‹‹　‹　<b>1</b>　›　››</span></div>`}
function slug(value){return value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}
function table(headers,rows,empty=false,rowLinks=[]){return `<div class="data-table"><table><thead><tr>${headers.map((h,i)=>`<th>${h}${i===0?' ↑':''}</th>`).join('')}</tr></thead><tbody>${empty?`<tr><td colspan="${headers.length}" class="empty">No results</td></tr>`:rows.map((r,ri)=>`<tr data-record="${ri}"${rowLinks[ri]?` data-route="${rowLinks[ri]}" tabindex="0"`:''}>${headers.map((_,i)=>`<td>${r[i]??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function clientsScreen(){const links=clients.map(r=>`client-${slug(r[0])}`);return `${tools('Search clients …','<button class="export" data-export="Client CSV">Export CSV ⇩</button>')}${table(['Name','Email','Phone','Date Added','Last Activity'],clients,false,links)}${pager(clients.length)}`}

const statusSets={
  'initial-stage':[['Not Assigned','neutral'],['Assigned','info'],['Contact Attempted','warning'],['Appointment Booked','progress'],['Documents Requested','attention'],['Ready to Progress','success']],
  'active-prospect':[['Qualified','success'],['Fact Find Started','progress'],['Awaiting Documents','warning'],['Appointment Booked','info'],['Follow-up Due','attention'],['Ready to Submit','success']],
  submitted:[['Submitted','progress'],['Awaiting Lender','warning'],['Valuation Booked','info'],['Under Review','progress'],['Further Info Required','attention'],['Approved','success']],
  offered:[['Offer Issued','success'],['Offer Accepted','success'],['Awaiting Solicitor','warning'],['Exchange Pending','progress'],['Offer Extension','attention'],['Completion Booked','info']],
  completed:[['Completed','success'],['Funds Released','success'],['Completion Confirmed','info'],['Welcome Call Due','warning'],['Review Scheduled','progress'],['Archived','neutral']],
  'on-risk':[['On Risk','success'],['Policy Active','success'],['Documents Issued','info'],['Trust Pending','warning'],['Review Due','progress'],['Client Action Required','attention']],
  replaced:[['Replaced','neutral'],['New Policy Active','success'],['Cancellation Pending','warning'],['Provider Confirmed','info'],['Documents Pending','attention'],['Complete','success']],
  'not-proceeding':[['Client Withdrew','neutral'],['Unable to Contact','attention'],['Criteria Not Met','warning'],['Alternative Chosen','neutral'],['Paused','info'],['Closed','neutral']]
};
function caseRows(headers,stage){return caseNames.map((name,i)=>headers.map(h=>{
  if(h==='Type')return `<span class="case-type">${i%3===0?'↔':'⌂'}</span>`; if(h==='Advisor')return i%2?'<span class="avatar tiny">DB</span>':'—'; if(h==='Client')return `<b>${name}</b>`; if(h.includes('Ref'))return `MAB26${String(i+1).padStart(3,'0')}X`; if(['Created','Submitted','Completion','On Risk'].includes(h))return `${5+i} Sep 2026`; if(['Lender','Existing Lender','New Lender','Provider'].includes(h))return ['Halifax','Nationwide','Aviva'][i%3]; if(h==='Introducer')return i%2?'Dashly':'Direct'; if(h==='Premium')return `£${42+i*8}.50`; if(h==='Applications')return '<span class="dots">○ ○ ○</span>'; if(h==='Months to End Date')return '<span class="timeline-mini"><i></i><i></i><i></i><i></i></span>'; if(h==='Tasks')return i%2?'1 <em>!</em>':'—'; if(h==='Status'){const [label,tone]=(statusSets[stage]||statusSets['initial-stage'])[i%6];return `<span class="status ${tone}">${label}</span>`} if(['Proceeding','Fact Find','Appointment','H2B','Valuation Status'].includes(h))return '<span class="ring"></span>'; if(h==='Last Action')return `${i+1} mth${i?'s':''} ago`; if(['Ending In','Product End','Offer Expiry'].includes(h))return `${i+2} mths`; return '—';
}));}
function remortgageRows(stage){
  if(stage==='initial-stage')return [
    ['—','<b>Fallon Test</b>','5 years ago','10 mths ago','<span class="timeline-mini"><i></i><i></i><i></i><i></i></span>','<span class="status attention">Missed</span>'],
    ['—','<b>Ivan Sevcik</b>','2 mths','6 mths ago','<span class="timeline-mini"><i></i><i></i><i></i><i></i></span>','<span class="status warning">Warming Up</span>']
  ];
  if(stage==='active-prospect')return ['Fallon Test','Ivan Sevcik','John Scott'].map((name,i)=>[
    '<span class="case-type">↔</span>','—',`<b>${name}</b>`,['Halifax','Nationwide','Santander'][i],`MAB20${12+i}BS`,`${1+i} mth${i?'s':''}`,'<span class="ring"></span>',`${2+i} mths ago`,i===1?'1 <em>!</em>':'—','<span class="status progress">Engaged</span>'
  ]);
  return [];
}
function remortgagePipeline(stage){const headers=remortgageColumns[stage],rows=remortgageRows(stage),links=stage==='initial-stage'?['case-remortgages-initial-stage-fallon-test','case-remortgages-initial-stage-ivan-sevcik']:stage==='active-prospect'?['case-remortgages-active-prospect-fallon-test','case-remortgages-active-prospect-ivan-sevcik','case-remortgages-active-prospect-john-scott']:[];return `${gauges()}${tools('Search remortgages …',dropdown('Filters',['Filters','Assigned to Me','All Advisors']))}<div class="export-row"><button class="export" data-export="Remortgage CSV">Export CSV ⇩</button></div>${table(headers,rows,!rows.length,links)}${rows.length?pager(rows.length):'<div class="pager"><span>Showing 1 - 100 of 0</span></div>'}`}
function pipelineScreen(family,stage){if(family==='remortgages')return remortgagePipeline(stage);const map=family==='mortgages'?mortgageColumns:protectionColumns;const headers=map[stage],rows=caseRows(headers,stage),label=family==='protection'?'protection':family;const assigned='<label class="switch-label">Assigned to Me<input type="checkbox"><i></i></label>';const links=caseNames.map(name=>`case-${family}-${stage}-${slug(name)}`);return `${tools(`Search ${label} …`,assigned)}<div class="export-row"><button class="export" data-export="${family} CSV">Export CSV ⇩</button></div>${table(headers,rows,false,links)}${pager(rows.length)}`}
function gauges(){return `<div class="gauge-grid">${[['12 months','0','green'],['9 months','0','mint'],['5 months','0','gold'],['3 months','1','orange'],['Less than 1 month','4','red']].map(([l,n,c])=>`<article><div class="gauge ${c}"><i></i></div><strong>${n}</strong><span>${l}</span></article>`).join('')}</div>`}

function tasksScreen(){return `<div class="tabs" data-tabs><button class="active">My Tasks</button><button>Delegated Tasks</button><button>Team Tasks</button></div>${tools('Search tasks …','<label class="switch-label">View Completed<input type="checkbox"><i></i></label>')}<div class="item-count">Items:　<b>10</b>　20　30　100</div>${table(['Type','Creation Date','Creator','Client','Summary','Deadline'],[],true)}${pager(0)}`}
function directoryScreen(type){const isUser=type==='users';const heads=isUser?['Name','User Type','Email','2FA','Office 365','Twenty7tec','Line Manager','Last Login']:['Introducer Name','Type','Fees Waived','Contact Name','Last Login','Active Referrals'];const source=isUser?clients.slice(0,6):clients.slice(2,8);const rows=source.map((r,i)=>isUser?[r[0],i%2?'Advisor - Mortgages':'Administrator',r[1],'<span class="yes">●</span>','○','○',i%2?'Darran Brindley':'—',r[4]]:[r[0],i%2?'Estate Agent':'House Builder',i%3?'No':'Yes',caseNames[i],r[4],String(3+i)]);const links=source.map(r=>`${isUser?'user':'introducer'}-${slug(r[0])}`);return `${tools(`Search ${isUser?'users':'introducers'} …`)}<div class="item-count">Items:　10　20　30　<b>100</b></div>${table(heads,rows,false,links)}${pager(rows.length)}`}

function introducerReport(){return `<div class="report-tabs tabs"><button class="active">Summary</button><button>Divisions</button></div><div class="report-empty"><div class="report-selects">${dropdown('Select Introducer',['Dashly','MAB Central','Direct'])}${dropdown('Monthly',['Monthly','Quarterly','Annual'])}${dropdown('Year to Date',['Year to Date','Previous Year'])}</div><p>Select an Introducer to see reports.</p></div>`}
function managementReport(){return `${reportPanel('⌂','Mortgages',['Export All Mortgages','Export Report'],['New Business Applications','Remortgages','Value of Lending','Resubmissions','Value of Lending (Resub)'])}${reportPanel('◇','Protection',['Export On Risk Applications','Export All Cases','Export Report'],['Applications','Clients Sold to','Value of Premiums','Total Premium On Risk'])}`}
function reportPanel(icon,title,exports,columns){const rows=title==='Mortgages'?[['12','5','£3.1m','2','£480k']]:[['11','8','£6,840','£4,920']];return `<section class="report-panel"><header><span class="report-icon">${icon}</span><h2>${title}</h2><span class="panel-caret">⌄</span></header><div class="panel-exports">${exports.map(x=>`<button data-export="${x}">${x} ⇩</button>`).join('')}</div>${table(columns,rows)}</section>`}
function midasReport(){return `<section class="report-panel midas"><header><span class="report-icon pink">M</span><h2>Failed to Export</h2><span class="panel-caret">⌄</span></header><div class="panel-exports"><button data-export="Failed Protection Cases">Export Failed Protection Cases ⇩</button><button data-export="Failed Mortgage Cases">Export Failed Mortgage Cases ⇩</button></div></section>`}

