function findClient(key){const row=clients.find(r=>slug(r[0])===key);return row?{name:row[0],email:row[1],phone:row[2],created:row[3],value:'£250k – £500k',notes:'Client record managed through the MAB portal.'}:people[key]||people['peter-heron']}
function detailTabs(active='general',family='mortgages'){const labels=family==='remortgages'?[['General','general'],['Journal','journal'],['Documents','documents'],['Tasks','tasks']]:[['General','general'],['Journal','journal'],['Documents','documents'],['Fact Find','fact-find'],['Tasks','tasks']];return `<div class="workspace-tabs" data-workspace-tabs>${labels.map(([label,key])=>`<button data-detail-tab="${key}" class="${key===active?'active':''}">${label}${key==='tasks'&&family!=='remortgages'?'<span class="tab-count">1</span>':''}</button>`).join('')}<button data-detail-tab="suggest" class="suggest-tab ${active==='suggest'?'active':''}">✧ Suggest</button></div>`}
function actionButton(icon,label){return `<button class="workspace-action" data-action="${label}"><span>${icon}</span>${label}</button>`}
function detailHeader(person,back,family='mortgages'){const isRemortgage=family==='remortgages';return `<div class="workspace-title"><a href="#${back}" aria-label="Back">←</a><span class="avatar">${person.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><b>${person.name}</b></div><div class="workspace-actions">${isRemortgage?'<button class="top-action log-contact" data-action="Log Contact">Log Contact</button>':''}${actionButton('▤','Send')}${actionButton('✓','Task')}${actionButton('▣','Book')}${actionButton('≡','Note')}${actionButton('☎','Log')}${actionButton('⚑','Pin')}${actionButton('•••','More')}<span class="header-status">${isRemortgage?'Awaiting First Contact':'In Progress'}</span></div>`}
function clientHeader(person){return `<div class="workspace-title"><a href="#clients" aria-label="Back">←</a><span class="avatar">${person.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><b>${person.name}</b></div><div class="workspace-actions"><button class="top-action" data-action="Add Mortgage">＋ Add Mortgage</button><button class="top-action" data-action="Add Protection">＋ Add Protection</button>${actionButton('✎','Edit')}</div>`}
function introducerHeader(person){return `<div class="workspace-title"><a href="#introducers" aria-label="Back">←</a><b>${person.name}</b></div><div class="workspace-actions"><button class="top-action" data-action="Add User">＋ Add User</button><button class="top-action" data-action="Add Region">＋ Add Region</button><button class="top-action" data-action="Add Site">＋ Add Site</button>${actionButton('✎','Edit')}</div>`}
function infoCard(label,value,action=''){return `<article class="info-card"><small>${label}</small><strong>${value}</strong>${action?`<button data-action="${action}">${action}</button>`:''}</article>`}
function field(label,value,wide=false){return `<div class="detail-field ${wide?'wide':''}"><small>${label}</small><p>${value}</p></div>`}
function caseGeneral(family,stage,person){const isProtection=family==='protection',isRemortgage=family==='remortgages';return `<div class="summary-grid">${infoCard('Next Action',stage==='initial-stage'?'Complete Fact Find':'Review case')}${infoCard('Waiting On',stage==='submitted'?'Lender':'Client')}${infoCard('Date Created',person.created)}${infoCard('Appointment','16 Sep 2026 13:15','Arrange')}${infoCard(isProtection?'Protection Review':'Help to Buy','—','Update Status')}${infoCard(isProtection?'Fact Find':'Fact Find','12 days ago','View')}</div><section class="workspace-panel application-panel"><div class="panel-heading"><h2>Applications</h2></div><p class="panel-empty">Your applications will appear here. You can create an application once the client sheet is approved.</p></section><section class="workspace-panel"><div class="panel-heading"><h2>${isProtection?'Protection':'Mortgage'} Details</h2><button class="icon-edit" data-action="Edit">Edit</button></div><div class="detail-grid">${field('MAB Ref','MAB2609YJ')}${field('Category',isProtection?'Protection':isRemortgage?'Remortgage':'Purchase')}${field('First Time Buyer','No')}${field('Type',isProtection?'Life & Critical Illness':'Residential')}${field('Scheme',isProtection?'Standard':'Help to buy')}${field('Introducer','MAB Central')}${field('Region','UK')}${field('Site','Site One')}${field('Sales Advisor','Darran Brindley')}${field(isProtection?'Monthly Budget':'Property Value',isProtection?'£75 – £125':person.value)}${field('Referral Type','Other')}${field('Desired Qualification','Advice and Recommendation')}${field('Notes',person.notes,true)}</div></section><section class="workspace-panel"><div class="panel-heading"><h2>Applicants Details</h2></div><div class="applicant-card"><span class="avatar large">${person.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><small>Lead Applicant</small><h3>${person.name}</h3></div></div><div class="detail-grid compact-grid">${field('Client Email',person.email)}${field('Client Phone',person.phone)}${field('WhatsApp','✓ Opted-in')}${field('Credit Report Opt Out','Opted In')}${field('Correspondence Address','24 Westfield Road, Bristol',true)}${field('Contact By','Email, Phone, Message')}</div></section>`}
function remortgageGeneral(person){return `<div class="summary-grid">${infoCard('Next Action','Attempt contact')}${infoCard('Waiting On','Advisor')}${infoCard('Product End Date','1 Jan 2022 (-1719 days)')}${infoCard('Appointment','—','Arrange')}${infoCard('Fact Find','—')}${infoCard('PT Declaration','—')}</div><section class="workspace-panel application-panel"><div class="panel-heading"><h2>Applications</h2></div><p class="panel-empty">Your applications will appear here. You can create an application once the client sheet is approved.</p></section><section class="workspace-panel"><div class="panel-heading"><h2>Remortgage Details</h2></div><div class="detail-grid">${field('Heron Ref','MFT2012BS')}${field('Standard Variable Rate','%')}${field('New Monthly Payments','—')}${field('Category','Product Transfer')}${field('Type','Other')}${field('Scheme','…')}${field('Advisor','Daniel Advisor')}${field('Notes','Test',true)}</div></section><section class="workspace-panel"><div class="panel-heading"><h2>Applicants Details</h2></div><div class="applicant-card"><span class="avatar large">${person.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><small>Lead Applicant</small><h3>${person.name}</h3></div></div><div class="detail-grid compact-grid">${field('Client Email',person.name==='Fallon Test'?'georgia+sprint@sprint.com':person.email)}${field('Client Phone',person.name==='Fallon Test'?'+44 7738732784':person.phone)}${field('WhatsApp','✓ Opted-in')}${field('Credit Report Opt Out','Opted In')}${field('Contact By','Email, Message')}</div></section><section class="workspace-panel"><div class="panel-heading"><h2>Current Mortgage Details</h2><button class="secondary" data-toast="Current mortgage opened">↗ View</button></div><div class="detail-grid">${field('Property Valuation','£400,000.00')}${field('Date of Valuation','1 Jul 2019')}${field('Category','Remortgage')}${field('First Time Buyer','No')}${field('Client Type','Let to Buy')}${field('Scheme','…')}${field('Introducer','Sheldon Estates')}${field('Branch','Southern Homes Division')}${field('Advisor','Robin Thomas')}${field('Reference','…')}${field('Previous Situation','…')}</div></section>`}
function journalContent(person){return `${tools('Search journal …',`<div class="journal-actions"><button class="secondary">↻ Refresh entries</button>${dropdown('Select Application',['Select Application','Mortgage application','Protection application'])}</div>`)}<section class="workspace-panel"><div class="timeline"><article><i>↻</i><div><b>Status Change: ${person.name}</b><small>4 Sep 2026 09:46</small><p>Status is now 'In progress'</p><p>Previous Status: Awaiting first contact　·　New Status: In progress　·　Next Action: Complete fact find　·　Waiting On: Client</p></div></article><article><i>☎</i><div><b>Client Contact Logged: ${person.name}</b><small>4 Sep 2026 09:46</small><p>Client was successfully contacted</p><p>Direction: Outbound　·　Result: Spoken to　·　Specific Type: Proceeding</p></div></article><article><i>▣</i><div><b>Appointment Booked: ${person.name}</b><small>4 Sep 2026 09:45</small><p>Phone appointment booked for Phone</p><p>Type: Phone　·　Host: Darran Brindley　·　Date/Time: Wed 16 Sept 2026 13:15</p></div></article><article><i>＋</i><div><b>Fact Find Started: ${person.name}</b><small>4 Sep 2026 09:28</small><p>${person.name} has started the Fact Find</p></div></article></div></section>`}
function remortgageJournal(){return `<section class="workspace-panel pinned-note"><div class="panel-heading"><div><small>Added by: Chris Wilson</small><strong>12 Nov, 2025 16:20</strong></div><button class="secondary" data-toast="Edit opened">Edit</button></div><p>Test</p></section>${tools('Search journal …',`<div class="journal-actions"><button class="secondary">↻ Refresh entries</button>${dropdown('Select Application',['Select Application'])}</div>`)}<section class="workspace-panel"><div class="timeline"><article><i>⚑</i><div><b>Pinned Note Added: Chris Wilson</b><small>12 Nov, 2025 16:20</small><p>A pinned note was added</p><p>Test</p></div></article><article><i>✎</i><div><b>Client Updated: Zoe Sheldon</b><small>30 Oct, 2024 10:40</small><p>Client email was updated</p><p>Client email was changed from zoe.me@hotmail.com to georgia+sprint@sprint.com</p></div></article><article><i>✎</i><div><b>Client Updated: Zoe Sheldon</b><small>30 Oct, 2024 10:34</small><p>Client contact details were updated</p><p>Client email and phone number were changed.</p></div></article><article><i>＋</i><div><b>Remortgage Created: Super Admin UAT</b><small>17 Dec, 2020 08:55</small><p>Remortgage created from mortgage 10</p></div></article></div></section>`}
function documentsContent(family='mortgages'){const headers=family==='remortgages'?['Name','Size','Type','Uploaded By','Status','Timestamp']:['Name','Size','Type','Uploaded By','Application','Status','Timestamp'];return `${tools('Search documents …','<button class="export" data-export="Document ZIP">Download ZIP ⇩</button>')}<div class="item-count">Items:　10　20　30　<b>100</b></div>${table(headers,[],true)}<div class="pager"><span>Showing 1 - 100 of 0</span></div>`}
function tasksContent(family='mortgages'){const headers=family==='remortgages'?['Creation Date','Assignee','Summary','Due Date']:['Creation Date','Assignee','Application','Summary','Due Date'];const rows=family==='remortgages'?[]:[['4 Sep 2026','Darran Brindley','—','Initial call','11 Sep 2026']];return `${tools('Search tasks …','<label class="switch-label">View Completed<input type="checkbox"><i></i></label>')}<div class="item-count">Items:　10　20　30　<b>100</b></div>${table(headers,rows,!rows.length)}${rows.length?pager(rows.length):'<div class="pager"><span>Showing 1 - 100 of 0</span></div>'}`}
function suggestContent(kind,person,context={}){const family=context.family||'client',stage=context.stage||'active';const caseIdeas=family==='protection'?[['Review protection priorities','Confirm benefit amounts, term and budget before preparing recommendations.','High'],['Check mortgage dependency','The mortgage case may affect the recommended protection term and level of cover.','Medium'],['Draft review message',`Invite ${person.name} to a short protection review and explain the documents needed.`,'Ready']]:family==='remortgages'?[['Confirm product end date','The recorded end date is approaching. Confirm the latest mortgage statement and early repayment charge.','High'],['Run retention comparison','Compare a product transfer with whole-of-market remortgage options.','Medium'],['Prepare document request',`Ask ${person.name} for an up-to-date mortgage statement and latest income evidence.`,'Ready']]:[['Arrange first conversation','No appointment is recorded. Offer three appointment times and confirm the customer’s priorities.','High'],['Request key documents','Ask for three months of bank statements, latest payslips and proof of deposit.','Medium'],['Draft welcome message',`Send ${person.name} a friendly introduction with next steps and the secure-document checklist.`,'Ready']];const clientIdeas=[['Connect open cases','Review whether the mortgage and protection records should share the same fact find.','High'],['Resolve outstanding tasks','Three client tasks remain open, including one due today.','Medium'],['Prepare progress update',`Draft a concise update covering all current work for ${person.name}.`,'Ready']];const introducerIdeas=[['Share pipeline update','Six active referrals can be included in a concise partner update.','High'],['Check dormant referrals','Two referrals have had no recorded activity for more than seven days.','Medium'],['Draft partner message',`Thank ${person.name} and summarise the latest referral outcomes without exposing sensitive customer data.`,'Ready']];const userIdeas=[['Review access level','This user has export access. Confirm it is still appropriate for their role.','Medium'],['Complete integration check','Microsoft 365 and Twenty7tec are connected and healthy.','Complete'],['Prepare coaching summary',`Create a short activity summary for ${person.name} using their recent case and task data.`,'Ready']];const ideas=kind==='case'?caseIdeas:kind==='client'?clientIdeas:kind==='introducer'?introducerIdeas:userIdeas;return `<section class="suggest-hero"><div class="suggest-mark">✧</div><div><span>MAB Assist</span><h1>Suggested next steps for ${person.name}</h1><p>Suggestions are based on this record’s stage, activity, tasks and available documents. Review each item before applying it.</p></div><button class="secondary" data-toast="Suggestions refreshed">↻ Refresh</button></section><div class="suggest-layout"><section class="workspace-panel suggestion-list"><div class="panel-heading"><div><h2>Recommended actions</h2><p>${kind==='case'?`${family.replace(/^./,x=>x.toUpperCase())} · ${stage.replaceAll('-',' ')}`:'Prioritised from the current record'}</p></div><span class="suggest-count">${ideas.length} suggestions</span></div>${ideas.map(([title,copy,priority],i)=>`<article class="suggestion-card"><span class="suggestion-number">${i+1}</span><div><div class="suggestion-title"><h3>${title}</h3><span class="priority ${priority.toLowerCase()}">${priority}</span></div><p>${copy}</p><div class="suggestion-actions"><button class="primary" data-toast="${priority==='Ready'?'Draft created':'Suggestion added to tasks'}">${priority==='Ready'?'Create draft':'Add to tasks'}</button><button class="secondary" data-toast="Suggestion dismissed">Dismiss</button></div></div></article>`).join('')}</section><aside class="suggest-side"><section class="workspace-panel readiness-card"><div class="panel-heading"><h2>Record readiness</h2><strong>${kind==='case'?'72':'84'}%</strong></div><div class="readiness-bar"><i style="width:${kind==='case'?'72':'84'}%"></i></div>${[['Contact details',true],['Consent recorded',true],['Identity verified',true],['Income evidence',kind!=='case'],['Appointment booked',false]].map(([label,done])=>`<p><span class="check-state ${done?'done':''}">${done?'✓':'!'}</span>${label}</p>`).join('')}</section><section class="workspace-panel"><div class="panel-heading"><h2>Ask MAB Assist</h2></div><div class="prompt-list">${['Summarise this record','What is missing?','Draft a client update'].map(q=>`<button data-toast="Prompt added to MAB assistant">${q}<span>›</span></button>`).join('')}</div></section></aside></div><section class="suggest-disclaimer">✧ AI-generated suggestions may be incomplete. Check suitability, compliance requirements and customer information before taking action.</section>`}
function caseDetail(route){const bits=route.split('-'),family=bits[1],stages=family==='protection'?Object.keys(protectionColumns):family==='remortgages'?Object.keys(remortgageColumns):Object.keys(mortgageColumns);const stage=stages.find(s=>route.includes(`-${s}-`))||'initial-stage';const key=route.slice(route.indexOf(`-${stage}-`)+stage.length+2);const person=findClient(key);const active=sessionStorage.getItem(`tab-${route}`)||'general';const isRemortgage=family==='remortgages';const content=active==='general'?(isRemortgage?remortgageGeneral(person):caseGeneral(family,stage,person)):active==='journal'?(isRemortgage?remortgageJournal():journalContent(person)):active==='documents'?documentsContent(family):active==='fact-find'?'<div class="fact-find-view"></div>':active==='tasks'?tasksContent(family):suggestContent();return `<div class="workspace">${detailTabs(active,family)}<div class="workspace-body">${content}</div></div>`}
function clientDetail(route){const person=findClient(route.replace('client-',''));return `<div class="workspace"><div class="workspace-body client-source"><div class="summary-grid single-summary">${infoCard('Last Activity','—')}</div><section class="workspace-panel"><div class="panel-heading"><h2>Client Details</h2><button class="icon-edit" data-toast="Edit opened">Edit</button></div><div class="detail-grid">${field('Name',person.name)}${field('Email',person.email)}${field('Phone',person.phone)}${field('Date Added',person.created)}${field('Credit Report','Yes')}</div></section><section class="workspace-panel"><div class="panel-heading"><h2>Contact Preferences</h2><button class="icon-edit" data-toast="Edit opened">Edit</button></div><h3>Essential Updates</h3><div class="preference-grid">${field('Whatsapp','✓ Opted-in')}${field('Post','✓ Opted-in')}${field('Remortgage Reminders','✓ Opted-in')}${field('Contact Note','Test')}</div><h3>Optional Updates</h3><div class="preference-grid">${field('Email','✓ Opted-in')}${field('Phone','✓ Opted-in')}${field('WhatsApp','✓ Opted-in')}${field('Post','✓ Opted-in')}${field('Newsletter','✓ Opted-in')}</div></section>${table(['Type','Created','Role','Reference','End/Claw Back Date','Status'],[['⌂',person.created,'Lead','MAB2603HA - 56','—','Not Assigned']],false,[`case-mortgages-initial-stage-${slug(person.name)}`])}</div></div>`}
function introducerTabs(active){const labels=[['General','general'],['Regions','regions'],['Sites','sites'],['Users','users'],['Links','links'],['Mortgages','mortgages']];return `<div class="workspace-tabs">${labels.map(([label,key])=>`<button data-detail-tab="${key}" class="${active===key?'active':''}">${label}</button>`).join('')}</div>`}
function introducerDetail(route){const person=findClient(route.replace('introducer-','')),active=sessionStorage.getItem(`tab-${route}`)||'general';let content;if(active==='regions')content=`${tools('Search regions …')}${table(['Region Name','No. of Sites','No. of Users'],[['England','4','1'],['Wales','1','0']])}${pager(2)}`;else if(active==='sites')content=`${tools('Search sites …',dropdown('Select Region',['Select Region','England','Wales']))}<div class="item-count">Items:　10　20　30　<b>100</b></div>${table(['Site Name','Region','Sales Advisors','Site Admins'],[['Bristol','England','0','0'],['Cardiff','Wales','0','0'],['Leeds','England','1','0']])}${pager(3)}`;else if(active==='users')content=`${tools('Search users …',dropdown('Select Region',['Select Region','England','Wales'])+dropdown('Select Site',['Select Site','Bristol','Cardiff']))}${table(['Name','Username','Type','Email','Phone','Last Activity'],[[person.name,slug(person.name),'Introducer Admin',person.email,person.phone,'—'],['Graham Burton','graham.burton','Sales Consultant','graham.burton@example.com','+44 1231231','28 Apr 2026']])}${pager(2)}`;else if(active==='links')content=`<section class="workspace-panel links-panel"><h2>QR Code</h2><div><button class="secondary">Export SVG ⇩</button><button class="secondary">Export PNG ⇩</button></div></section><section class="workspace-panel"><h2>Referral Link</h2><button class="secondary">Copy link</button></section><section class="workspace-panel"><h2>API Key</h2><a href="#">API Documentation</a><button class="secondary">Copy key</button></section>`;else if(active==='mortgages')content=`${tools('Search mortgages …','<button class="export">Export CSV ⇩</button>')}<div class="item-count">Items:　10　20　30　<b>100</b></div>${table(['Client Name','Created','Sales Advisor','Advisor','Waiting On','Last Action','Qualified Up To','Status'],caseNames.map((n,i)=>[n,`${4+i} Sep 2026`,person.name,'Darran Brindley',i%2?'Client':'Advisor',`${i+1} mths ago`,i%2?'£250,000':'—',i%2?'In Progress':'Awaiting Qualification']))}${pager(caseNames.length)}`;else content=`<div class="summary-grid">${infoCard('Active Referrals','28')}${infoCard('Values','—')}${infoCard('Approval','0%')}${infoCard('Type','House Builder')}${infoCard('Last Activity','6 years ago')}</div><section class="workspace-panel"><div class="detail-grid">${field('Admin Name',person.name)}${field('Admin Email',person.email)}${field('Admin Phone',person.phone)}${field('Advisors','Darran Brindley, Sarah Taylor',true)}</div></section>`;return `<div class="workspace">${introducerTabs(active)}<div class="workspace-body">${content}</div></div>`}

// The Suggest view deliberately mirrors the source portal. This is a visual
// branding prototype, so the original empty states and wording are preserved.
function suggestContent(){return `<div class="suggest-original"><section class="suggest-section"><header><h1>Quick Actions</h1><p>When a client provides information by phone or Zoom, you can apply it to their Fact Find or Client Sheet easily here.</p></header><div class="suggest-empty"><span class="empty-orbit clock-icon">◷</span><h2>No actionable items</h2><p>You do not have any actionable items at this time</p></div></section><section class="suggest-section"><header><h1>Alerts</h1><p>Alerts are flagged items which require your attention</p></header><div class="suggest-empty"><span class="empty-orbit alert-icon">!</span><h2>No alerts</h2><p>You do not have any alerts at this time</p></div></section></div>`}

function choiceSet(label,name,items,type='radio'){return `<fieldset class="choice-set"><legend>${label}</legend><div>${items.map((item,i)=>`<label><input type="${type}" name="${name}" value="${item}"${i===0&&type==='radio'?' checked':''}><span>${item}</span></label>`).join('')}</div></fieldset>`}
function selectField(label,items,value=''){return `<label>${label}<select>${items.map(item=>`<option${item===value?' selected':''}>${item}</option>`).join('')}</select></label>`}
function mockActions(primary){return `<div class="dialog-actions"><button type="button" class="secondary" data-dialog-cancel>Cancel</button><button type="submit" class="primary">${primary}</button></div>`}
function addReferralForm(){return `${choiceSet('Referral Type','referral-type',['Vendor','Offer qualification','Existing client','Other'])}${choiceSet('Property Value','property-value',['Less than £250k','£250k – £500k','£500k – £1M','More than £1M'])}${choiceSet('Client Category','client-category',['Purchase','Remortgage'])}${choiceSet('Client Type','client-type',['Let to Buy','Buy to Let','Mover','Other'])}${choiceSet('Scheme (Optional)','scheme',['Help to buy','Shared ownership','Discount market sale'])}${choiceSet('Contact by','contact-by',['Email','Phone','Message'],'checkbox')}<div class="dialog-grid"><label>Reference (Optional)<input value="MAB-PROTOTYPE-01"></label><label>Notes<textarea>Customer is looking to review borrowing options and would prefer an initial call after 5pm.</textarea></label>${selectField('Client',['Select Client','Abbey Smith','Adam Jones','Fallon Test','Ivan Sevcik'],'Select Client')}${selectField('Introducer',['Select Introducer','Direct','Dashly','Sheldon Estates'],'Select Introducer')}</div>${mockActions('Add Referral')}`}
function genericActionForm(action,person){const name=person?.name||'Peter Heron';if(action==='Arrange')return genericActionForm('Book',person);if(action==='Update Status')return genericActionForm('More',person);if(action==='View')return `<div class="mock-record-summary"><p><small>Reference</small><strong>MAB2609YJ</strong></p><p><small>Client</small><strong>${name}</strong></p><p><small>Status</small><strong>In Progress</strong></p><p><small>Last activity</small><strong>4 Sep 2026</strong></p></div>${mockActions('Close')}`;if(action==='Edit')return `<label>Name<input value="${name}"></label><label>Email address<input type="email" value="${person?.email||'customer@example.com'}"></label><label>Phone<input value="${person?.phone||'+44 7700 900123'}"></label><label>Notes<textarea>${person?.notes||'Prototype record details.'}</textarea></label>${mockActions('Save Changes')}`;if(action==='Add Referral'||action==='Add Mortgage')return addReferralForm();if(action==='Add Protection')return `${selectField('Client',[name,'Abbey Smith','Adam Jones'],name)}${choiceSet('Protection Type','protection-type',['Life','Critical Illness','Income Protection','Family Income Benefit'])}${choiceSet('Monthly Budget','monthly-budget',['Less than £50','£50 – £100','£100 – £200','More than £200'])}<label>Notes<textarea>Review protection alongside the mortgage recommendation.</textarea></label>${mockActions('Add Protection')}`;if(action==='Send')return `${selectField('Send by',['Email','Message','WhatsApp'],'Email')}<label>Subject<input value="Your mortgage update"></label><label>Message<textarea>Hi ${name}, here is a quick update on your case. Please get in touch if you have any questions.</textarea></label>${mockActions('Send')}`;if(action==='Task')return `<label>Summary<input value="Follow up with ${name}"></label>${selectField('Assignee',['Darran Brindley','Sarah Taylor','Michael Davis'],'Darran Brindley')}<div class="dialog-grid two"><label>Due date<input type="date" value="2026-09-21"></label>${selectField('Priority',['Normal','High','Urgent'],'Normal')}</div><label>Notes<textarea>Confirm the customer has received the latest update.</textarea></label>${mockActions('Add Task')}`;if(action==='Book')return `${selectField('Appointment type',['Phone','Video','In person'],'Phone')}<div class="dialog-grid two"><label>Date<input type="date" value="2026-09-22"></label><label>Time<input type="time" value="14:30"></label></div>${selectField('Host',['Darran Brindley','Sarah Taylor'],'Darran Brindley')}<label>Notes<textarea>Mortgage review appointment.</textarea></label>${mockActions('Book Appointment')}`;if(action==='Log'||action==='Log Contact')return `${choiceSet('Direction','contact-direction',['Outbound','Inbound'])}${selectField('Result',['Spoken to','Left voicemail','No answer','Email sent'],'Spoken to')}${selectField('Specific Type',['Proceeding','Follow up required','Not proceeding'],'Proceeding')}<label>Notes<textarea>Discussed next steps and agreed to follow up with the required documents.</textarea></label>${mockActions('Log Contact')}`;if(action==='Note'||action==='Pin')return `<label>${action==='Pin'?'Pinned note':'Note'}<textarea>${action==='Pin'?'Important customer preference: contact by email first.':'Customer called to discuss progress and next steps.'}</textarea></label><label class="check-row"><input type="checkbox"${action==='Pin'?' checked':''}> Pin this note to the top of the journal</label>${mockActions(action==='Pin'?'Pin Note':'Add Note')}`;if(action==='More')return `${selectField('Status',['Awaiting First Contact','In Progress','Awaiting Documents','On Hold'],'In Progress')}${selectField('Waiting On',['Client','Advisor','Lender','Introducer'],'Client')}<label>Reason / notes<textarea>Mock status update for prototype demonstration.</textarea></label>${mockActions('Update')}`;if(action==='Add Client')return `<div class="dialog-grid two"><label>First name<input value="Alex"></label><label>Last name<input value="Morgan"></label></div><label>Email address<input type="email" value="alex.morgan@example.com"></label><label>Phone<input value="+44 7700 900123"></label>${choiceSet('Contact by','new-contact-by',['Email','Phone','Message'],'checkbox')}${mockActions('Add Client')}`;if(action==='Add Introducer')return `<label>Introducer name<input value="MAB Partner Homes"></label>${selectField('Type',['Estate Agent','House Builder','Accountant','Other'],'Estate Agent')}<label>Contact name<input value="Jamie Taylor"></label><label>Email address<input type="email" value="jamie.taylor@example.com"></label><label>Phone<input value="+44 7700 900456"></label>${mockActions('Add Introducer')}`;if(action==='Add User')return `<div class="dialog-grid two"><label>First name<input value="Jamie"></label><label>Last name<input value="Taylor"></label></div><label>Email address<input type="email" value="jamie.taylor@example.com"></label>${selectField('User Type',['Introducer Admin','Sales Consultant'],'Sales Consultant')}${mockActions('Add User')}`;if(action==='Add Region')return `<label>Region name<input value="South West"></label>${mockActions('Add Region')}`;if(action==='Add Site')return `<label>Site name<input value="Bristol Central"></label>${selectField('Region',['England','Wales','South West'],'South West')}<label>Address<textarea>24 Westfield Road, Bristol</textarea></label>${mockActions('Add Site')}`;if(action==='Add MAB User')return `<div class="dialog-grid two"><label>First name<input value="Jamie"></label><label>Last name<input value="Taylor"></label></div><label>Email address<input type="email" value="jamie.taylor@mab.org.uk"></label>${selectField('User Type',['Administrator','Advisor - Mortgages','Advisor - Protection'],'Advisor - Mortgages')}${selectField('Line Manager',['Darran Brindley','Sarah Taylor'],'Darran Brindley')}${mockActions('Add MAB User')}`;return `<label>Details<textarea>Mock ${action.toLowerCase()} content for this prototype.</textarea></label>${mockActions(action)}`}
function openPrototypeAction(action){const d=document.querySelector('#form-dialog'),route=(location.hash||'#dashboard').slice(1),person=route.startsWith('case-')?getCaseMeta(route).person:route.startsWith('client-')?findClient(route.replace('client-','')):route.startsWith('introducer-')?findClient(route.replace('introducer-','')):null;d.classList.toggle('wide-dialog',action==='Add Referral'||action==='Add Mortgage');d.querySelector('.eyebrow').textContent='MAB portal prototype';d.querySelector('h2').textContent=action;d.querySelector('form').innerHTML=genericActionForm(action,person);d.querySelector('form').onsubmit=e=>{e.preventDefault();d.close();showToast(`${action} saved in prototype`)};d.showModal()}

function openUserEditor(person){const d=document.querySelector('#form-dialog');d.classList.remove('wide-dialog');d.querySelector('h2').textContent='Edit User';d.querySelector('form').innerHTML=`<label>First Name<input value="${person.name.split(' ')[0]||''}"></label><label>Last Name<input value="${person.name.split(' ').slice(1).join(' ')}"></label><label>Email Address<input type="email" value="${person.email}"></label><label>Phone<div class="phone-field"><span>+44</span><input value="${person.phone.replace('+44 ','')}"></div></label><label>Zoom extension number<input></label><label>Profile Photo<button type="button" class="upload-placeholder">Drag & Drop or click to add attachment</button></label><label>User Type<select><option>Administrator</option><option>Advisor - Mortgages</option><option>Advisor - Protection</option></select></label><label>Line Manager<select><option>Select Line Manager</option><option>Darran Brindley</option></select></label><label>Midas ID<input></label><div class="dialog-actions"><button type="button" class="danger">Delete</button><button type="button" class="secondary" onclick="this.closest('dialog').close();location.hash='users'">Cancel</button><button type="submit" class="primary">Update User</button></div>`;d.querySelector('form').onsubmit=e=>{e.preventDefault();d.close();location.hash='users'};d.showModal()}

function getCaseMeta(route){const family=route.split('-')[1];const map=family==='protection'?protectionColumns:family==='remortgages'?remortgageColumns:mortgageColumns;const stage=Object.keys(map).find(s=>route.includes(`-${s}-`))||'initial-stage';const key=route.slice(route.indexOf(`-${stage}-`)+stage.length+2);return {family,stage,key,person:findClient(key)}}
function setHeader(route){const top=document.querySelector('#topbar');if(route==='dashboard'){top.innerHTML=dashboardTopbar();top.className='topbar dashboard-topbar';return}top.className='topbar';if(route.startsWith('case-')){const x=getCaseMeta(route);top.innerHTML=detailHeader(x.person,`${x.family}-${x.stage}`,x.family)}else if(route.startsWith('client-'))top.innerHTML=clientHeader(findClient(route.replace('client-','')));else if(route.startsWith('introducer-'))top.innerHTML=introducerHeader(findClient(route.replace('introducer-','')));else if(route.startsWith('user-'))top.innerHTML=breadcrumb('MAB Users','','Add MAB User');else if(route==='clients')top.innerHTML=breadcrumb('Clients','','Add Client');else if(route==='tasks')top.innerHTML=breadcrumb('Tasks');else if(route==='introducers')top.innerHTML=breadcrumb('Introducers','','Add Introducer');else if(route==='users')top.innerHTML=breadcrumb('MAB Users','','Add MAB User');else if(route==='reports-management-report')top.innerHTML=breadcrumb('Reports','Management')+dropdown('This Week',['This Week','Last Week','This Month','This Quarter']);else if(route.endsWith('-report'))top.innerHTML=breadcrumb('Reports',routes[route]?.title||route.split('-')[0].replace(/^./,x=>x.toUpperCase()));else{const x=routes[route];top.innerHTML=breadcrumb(x.parent,x.title,x.family==='mortgages'?'Add Referral':x.family==='protection'?'Add Protection':'')}}
function setNav(route){let activeRoute=route;if(route.startsWith('case-')){const x=getCaseMeta(route);activeRoute=`${x.family}-${x.stage}`}else if(route.startsWith('client-'))activeRoute='clients';else if(route.startsWith('introducer-'))activeRoute='introducers';else if(route.startsWith('user-'))activeRoute='users';document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.hash==='#'+activeRoute));document.querySelectorAll('.nav-group').forEach(g=>g.classList.toggle('open',activeRoute.startsWith(g.dataset.group+'-')))}
function render(){const route=(location.hash||'#dashboard').slice(1);setHeader(route);setNav(route);let html='',editor=null;if(route==='dashboard')html=dashboard();else if(route==='clients')html=clientsScreen();else if(route==='tasks')html=tasksScreen();else if(route==='introducers'||route==='users')html=directoryScreen(route);else if(route.startsWith('case-'))html=caseDetail(route);else if(route.startsWith('client-'))html=clientDetail(route);else if(route.startsWith('introducer-'))html=introducerDetail(route);else if(route.startsWith('user-')){html=directoryScreen('users');editor=findClient(route.replace('user-',''))}else if(route==='reports-introducer-report')html=introducerReport();else if(route==='reports-management-report')html=managementReport();else if(route==='reports-midas-report')html=midasReport();else if(routes[route]){const x=routes[route];html=pipelineScreen(x.family,route.replace(x.family+'-',''))}else html='<div class="empty-state"><h1>Screen not found</h1><a href="#dashboard">Return to dashboard</a></div>';document.querySelector('#page').className='page'+(route==='dashboard'?' dashboard-page':'')+(route.startsWith('case-')||route.startsWith('client-')||route.startsWith('introducer-')?' workspace-page':'');document.querySelector('#page').innerHTML=html;document.title=`MAB Portal — ${route==='dashboard'?'Dashboard':routes[route]?.title||route}`;window.scrollTo({top:0});if(editor)setTimeout(()=>openUserEditor(editor),0)}
window.addEventListener('hashchange',render);render();

document.addEventListener('click',e=>{
  const cancelDialog=e.target.closest('[data-dialog-cancel]');if(cancelDialog){cancelDialog.closest('dialog').close();return}
  const action=e.target.closest('[data-action]');if(action){openPrototypeAction(action.dataset.action);return}
  const legacyAction=e.target.closest('[data-toast="Edit opened"],[data-toast="Current mortgage opened"]');if(legacyAction){openPrototypeAction(legacyAction.textContent.includes('View')?'View':'Edit');return}
  const exportAction=e.target.closest('[data-export],.links-panel button');if(exportAction){showToast(`${exportAction.dataset.export||exportAction.textContent.replace('⇩','').trim()} prepared in prototype`);return}
  const refreshAction=e.target.closest('.journal-actions .secondary');if(refreshAction){showToast('Journal entries refreshed');return}
  const workspaceTab=e.target.closest('[data-detail-tab]');if(workspaceTab){const route=(location.hash||'#dashboard').slice(1);sessionStorage.setItem(`tab-${route}`,workspaceTab.dataset.detailTab);render();return}
  const routedRow=e.target.closest('tr[data-route]');if(routedRow){location.hash=routedRow.dataset.route;return}
  const toastTarget=e.target.closest('[data-toast]');if(toastTarget){showToast(toastTarget.dataset.toast);return}
  const filter=e.target.closest('.filter');if(filter){const menu=document.querySelector(`[data-menu="${filter.dataset.filter}"]`);document.querySelectorAll('.menu').forEach(m=>{if(m!==menu)m.classList.remove('open')});menu.classList.toggle('open');filter.setAttribute('aria-expanded',menu.classList.contains('open'));return}
  const option=e.target.closest('.menu button');if(option){const wrap=option.closest('.filter-wrap'),button=wrap.querySelector('.filter');button.childNodes[0].textContent=option.textContent;button.setAttribute('aria-expanded','false');option.closest('.menu').classList.remove('open');const empty=document.querySelector('.report-empty>p');if(empty&&option.textContent!=='Monthly'&&!option.textContent.includes('Year'))empty.textContent=`Showing ${option.textContent} performance for the selected period.`;return}
  if(!e.target.closest('.filter-wrap'))document.querySelectorAll('.menu').forEach(m=>m.classList.remove('open'));
  const metric=e.target.closest('[data-name][data-value]');if(metric){const d=document.querySelector('#metric-dialog');d.querySelector('h2').textContent=metric.dataset.name;d.querySelector('.dialog-value').textContent=metric.dataset.value;d.showModal();return}
  const add=e.target.closest('[data-add]');if(add){openPrototypeAction(add.dataset.add);return}
  const tab=e.target.closest('[data-tabs] button,.tabs button');if(tab){tab.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===tab));return}
  const row=e.target.closest('tbody tr[data-record]');if(row){const d=document.querySelector('#form-dialog');d.querySelector('h2').textContent='Record details';d.showModal()}
});
document.addEventListener('keydown',e=>{const row=e.target.closest?.('tr[data-route]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();location.hash=row.dataset.route}});
function showToast(message){let toast=document.querySelector('.toast');if(!toast){toast=document.createElement('div');toast.className='toast';document.body.appendChild(toast)}toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2200)}
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){const q=e.target.value.toLowerCase();document.querySelectorAll('.data-table tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q))}});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close')?.addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d)d.close()})});
const formDialog=document.querySelector('#form-dialog');formDialog.querySelector('.secondary').addEventListener('click',()=>formDialog.close());formDialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();formDialog.close()});
const chat=document.querySelector('.chat-panel');document.querySelector('.chat-button').addEventListener('click',()=>chat.classList.toggle('open'));chat.querySelector('header button').addEventListener('click',()=>chat.classList.remove('open'));chat.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const input=e.target.querySelector('input');if(input.value.trim()){const p=document.createElement('p');p.textContent=input.value;Object.assign(p.style,{display:'block',marginLeft:'40px'});chat.querySelector('.chat-body').appendChild(p);input.value=''}});
